import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DH7DibUz.js";const f=JSON.parse('{"title":"Software","description":"","frontmatter":{"title":"Software"},"headers":[],"relativePath":"software/index.md","filePath":"software/index.md","lastUpdated":1794348538000}'),i={name:"software/index.md"};function l(n,e,s,h,p,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="software" tabindex="-1">Software <a class="header-anchor" href="#software" aria-label="Permalink to &quot;Software&quot;">​</a></h1><p>A succinct description and links to useful code repositories related to the activities of the Geocomputing Centre.</p><h2 id="centre-repositories" tabindex="-1">Centre repositories <a class="header-anchor" href="#centre-repositories" aria-label="Permalink to &quot;Centre repositories&quot;">​</a></h2><p>Tools, templates and material shared by the community are hosted on the <a href="https://github.com/Unil-SGC" target="_blank" rel="noreferrer">Unil-SGC GitHub organisation</a>:</p><ul><li><a href="https://github.com/Unil-SGC/geocomputing-coffee" target="_blank" rel="noreferrer">geocomputing-coffee</a>: material of the informal geocomputing coffee meet-ups, starting with a Git and GitHub demo.</li><li><a href="https://github.com/Unil-SGC/git-demo" target="_blank" rel="noreferrer">git-demo</a>: demo repository for a Git workflow.</li><li><a href="https://github.com/Unil-SGC/python-packaging" target="_blank" rel="noreferrer">python-packaging</a> and <a href="https://github.com/Unil-SGC/julia-packaging" target="_blank" rel="noreferrer">julia-packaging</a>: material of the <a href="/previews/pr-11/events/pkg-workshop">packaging workshop</a>, from a notebook to a package.</li><li><a href="https://github.com/Unil-SGC/IceFlow.jl" target="_blank" rel="noreferrer">IceFlow.jl</a>: shallow-ice-approximation routines used as the packaging example.</li><li><a href="https://github.com/Unil-SGC/AGDA-Rbook" target="_blank" rel="noreferrer">AGDA-Rbook</a>: book for the course &quot;Advanced geospatial data analysis&quot;.</li><li><a href="https://github.com/Unil-SGC/sgc-assets" target="_blank" rel="noreferrer">sgc-assets</a>: logo and other assets of the Centre.</li></ul><h2 id="julia-gpu-development" tabindex="-1">Julia GPU development <a class="header-anchor" href="#julia-gpu-development" aria-label="Permalink to &quot;Julia GPU development&quot;">​</a></h2><p>Ongoing development related to the <a href="https://gpu4geo.org" target="_blank" rel="noreferrer">GPU4GEO</a> PASC project is hosted on these organisations:</p><ul><li><a href="https://github.com/PTsolvers" target="_blank" rel="noreferrer">PTsolvers</a> organisation</li><li><a href="https://github.com/JuliaGeodynamics" target="_blank" rel="noreferrer">JuliaGeodynamics</a> organisation</li></ul><p>Building blocks:</p><ul><li><a href="https://github.com/omlins/ParallelStencil.jl" target="_blank" rel="noreferrer">ParallelStencil.jl</a>: package for writing high-level code for parallel high-performance stencil computations that can be deployed on both GPUs and CPUs.</li><li><a href="https://github.com/eth-cscs/ImplicitGlobalGrid.jl" target="_blank" rel="noreferrer">ImplicitGlobalGrid.jl</a>: almost trivial distributed parallelisation of stencil-based GPU and CPU applications on a regular staggered grid.</li><li><a href="https://github.com/JuliaGPU/AMDGPU.jl" target="_blank" rel="noreferrer">AMDGPU.jl</a>: AMD GPU (ROCm) programming in Julia.</li><li><a href="https://github.com/JuliaGPU/KernelAbstractions.jl" target="_blank" rel="noreferrer">KernelAbstractions.jl</a>: heterogeneous programming in Julia.</li></ul>',10)])])}const u=t(i,[["render",l]]);export{f as __pageData,u as default};
